  friends: `&lt;svg width=&quot;18&quot; height=&quot;18&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot;&gt;&lt;path d=&quot;M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2&quot;/&gt;&lt;circle cx=&quot;9&quot; cy=&quot;7&quot; r=&quot;4&quot;/&gt;&lt;path d=&quot;M23 21v-2a4 4 0 00-3-3.87&quot;/&gt;&lt;path d=&quot;M16 3.13a4 4 0 010 7.75&quot;/&gt;&lt;/svg&gt;`,
